200	export async function addMonitor(draft: unknown): Promise<Result<{ id: string; heartbeatUrl?: string }>> {
201	  const member = await begin();
202	  if (!isMember(member)) return member;
203	  if (!allowed(member.workspace, member.caller, "monitors:write")) return NOT_FOUND;
204	
205	  const parsed = parseMonitorDraft(draft);
206	  if (!parsed.ok) return { ok: false, reason: "Check the highlighted fields.", fieldErrors: parsed.fieldErrors };
207	  const row = parsed.row;
208	
209	  if (!(reach(member, await resolveApp(row.appId), "monitors:write"))) {
210	    return { ok: false, reason: "Pick the app this monitor belongs to.", fieldErrors: { appId: "Pick the app this monitor belongs to" } };
211	  }
212	  return createMonitor(member, row);
213	}
214	
215	/** A parsed row, in an app already resolved to the member's workspace with `monitors:write`
216	 *  there: the private-range check, then `create_monitor` with the plan's limits. Adding a monitor
217	 *  and adding suggested checks both come through here. */
218	async function createMonitor(member: Member, row: MonitorRow): Promise<Result<{ id: string; heartbeatUrl?: string }>> {
219	  if (isService(row.type)) return saveServiceMonitor(member, newMonitorId(), row, false);
220	  // The private-range refusal at create time (`targets.ts`). A DNS monitor asks a public
221	  // resolver about a name and never connects to it, and a heartbeat reaches no host of yours.
222	  if (row.targetHost && (row.type === "http" || row.type === "ssl" || row.type === "tcp")) {
223	    const target = await checkTarget(row.targetHost);
224	    if (!target.ok) return { ok: false, reason: target.reason, fieldErrors: { [row.type === "http" ? "url" : "host"]: target.reason } };
225	  }
226	
227	  const id = newMonitorId();
228	  const hb = row.type === "heartbeat" ? await newHeartbeat(id) : null;
229	  const L = member.entitlements.limits;
230	  const minInterval = L.httpIntervalMin * 60;
231	
232	  const { error } = await db().rpc("create_monitor", {
233	    p_workspace_id: member.workspace.id,
234	    p_id: id,
235	    p_app_id: row.appId,
236	    p_type: row.type,
237	    p_name: row.name,
238	    p_target: row.target,
239	    p_target_host: row.targetHost,
240	    p_interval_sec: row.fixedIntervalSec ?? minInterval,
241	    p_config: row.config as never,
242	    p_heartbeat_token_hash: hb?.hash ?? null,
243	    p_secrets: row.secrets.length
244	      ? row.secrets.map((s) => ({ name: s.name, sealed: seal(s.value, headerContext(id, s.name)) }))
245	      : null,
246	    p_max_monitors: L.monitors,
247	    p_max_heartbeats: L.heartbeats,
248	    p_max_assertions: L.assertions,
249	    p_max_heartbeat_assertions: L.heartbeatAssertions,
250	    // Builder's per-host allowance is fair use: no number below the monitor cap.
251	    p_per_host: L.perHost === "fair use" ? L.monitors : L.perHost,
252	    p_min_interval_sec: minInterval,
253	    p_heartbeat_token_sealed: hb?.sealed ?? null,
254	  });
255	  if (error) return refused(error, member, { host: row.targetHost, type: row.type });
256	  return hb ? { ok: true, id, heartbeatUrl: hb.url } : { ok: true, id };
257	}
258	
259	/** A monitor the builder may edit, as stored: its type, its app and its sealed header values,
260	 *  read in the member's workspace. An automatic monitor, or a type not live yet, is refused. */
261	async function storedMonitor(member: Member, monitorId: string): Promise<{ type: string; appId: string; target: string; sealed: Map<string, string> } | Refusal> {
262	  const ws = member.workspace.id;
263	  const [{ data: mon, error: monError }, { data: stored, error: storedError }] = await Promise.all([
264	    db().from("monitors").select("type, app_id, auto, target").eq("id", monitorId).eq("workspace_id", ws).maybeSingle(),
265	    db().from("monitor_secrets").select("name, sealed").eq("monitor_id", monitorId).eq("workspace_id", ws),
266	  ]);
267	  if (monError || storedError) return refused((monError ?? storedError)!, member);
268	  if (!mon) return NOT_FOUND;
269	  if (mon.auto || !isCreatable(mon.type)) return refused({ message: mon.auto ? "auto_monitor" : "type_not_available" }, member);
270	  return { type: mon.type, appId: mon.app_id, target: mon.target, sealed: new Map((stored ?? []).map((s) => [s.name, s.sealed])) };
271	}
272	
273	const isRefusal = (x: object): x is Refusal => "ok" in x;
274	
275	/** A kept secret header goes only to the address it was saved for. Any other address, another
276	 *  path on the same site included, means typing it again, so nobody who can edit a monitor can
277	 *  send a secret someone else typed to an address of their choosing, by saving or by testing:
278	 *  not to their own server, and not to a path of the same site that echoes what it's sent. */
279	function keptHeaderMoved(row: { type: string; target: string; secrets: readonly { name: string; value: string }[] }, storedTarget: string): Refusal | null {
280	  if (row.type !== "http" && row.type !== "supabase") return null;
281	  const address = (url: string) => {
282	    try {
283	      return new URL(url).href;
284	    } catch {
285	      return null;
286	    }
287	  };
288	  const kept = row.secrets.find((s) => !s.value);
289	  if (!kept || (address(row.target) !== null && address(row.target) === address(storedTarget))) return null;
290	  const reason = `Type ${kept.name} again: a kept value is only sent to the address it was saved for.`;
291	  return { ok: false, reason, fieldErrors: { [row.type === "supabase" ? "key" : "headers"]: reason } };
292	}
293	
294	/** Service saves cannot bypass preflight by posting an action directly or reusing a stale
295	 * browser test. Verification happens after ownership and budget checks, before any write. */
296	async function saveServiceMonitor(member: Member, id: string, row: MonitorRow, editing: boolean, stored = new Map<string, string>()): Promise<Result<{ id: string }>> {
297	  const spent = await spendTest(member);
298	  if (spent) return spent;
299	  let key = row.secrets[0]?.value ?? "";
300	  if (!key) {
301	    try { key = open(stored.get(SERVICE_KEY) ?? "", headerContext(id, SERVICE_KEY)); }
